import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { Carrito, ProductoCarrito } from '../models/carrito';

@Injectable({
  providedIn: 'root'
})
export class CarritoService {

  private carritoSeleccionadoSubject: BehaviorSubject<Carrito> = new BehaviorSubject<Carrito>(new Carrito());
  carritoSeleccionado$: Observable<Carrito> = this.carritoSeleccionadoSubject.asObservable();
  
  readonly URL = 'http://localhost:3000/api/carrito';

  constructor(private http: HttpClient) { }

  obtenerCarrito(idUsuario: string) {
    const url = `${this.URL}/obtener/${idUsuario}`;
    this.http.get<Carrito>(url).subscribe((res: Carrito) => {
      this.carritoSeleccionadoSubject.next(res);
    });
  }

  agregarAlCarrito(producto: ProductoCarrito) {
    this.http.post<Carrito>(`${this.URL}/agregar`, producto).subscribe((res: Carrito) => {
      this.carritoSeleccionadoSubject.next(res);
    });
  }

  eliminarDelCarrito(idProducto: string) {
    this.http.delete<Carrito>(`${this.URL}/${idProducto}`).subscribe((res: Carrito) => {
      this.carritoSeleccionadoSubject.next(res);
    });
  }

  vaciarCarrito() {
    this.http.delete<Carrito>(`${this.URL}/vaciar`).subscribe((res: Carrito) => {
      this.carritoSeleccionadoSubject.next(res);
    });
  }
}
